'use client'

import { useState } from 'react'
import { Power, ShieldCheck, Activity, Volume2 } from 'lucide-react'
import { toggleSystemSettingAction } from '@/app/actions/adminActions'

interface Settings {
  maintenance_mode: boolean
  voice_cloning_enabled: boolean
}

export default function SystemSwitches({ initialSettings }: { initialSettings: Settings }) {
  const [settings, setSettings] = useState(initialSettings)
  const [loading, setLoading] = useState<string | null>(null)

  const handleToggle = async (field: keyof Settings) => {
    setLoading(field)
    const res = await toggleSystemSettingAction(field, settings[field])
    if (res.success) {
      setSettings(prev => ({ ...prev, [field]: !prev[field] }))
    } else {
      alert(res.error)
    }
    setLoading(null)
  }

  return (
    <div className="bg-white rounded-[2.5rem] shadow-sm border border-gray-100 overflow-hidden mt-12 animate-in fade-in slide-in-from-bottom-10 duration-1000">
      <div className="p-8 border-b border-gray-50 flex items-center justify-between bg-white">
        <h2 className="text-2xl font-black text-gray-900 flex items-center gap-3">
          <Power className="text-red-500" />
          Sistem Şalterleri (Feature Flags)
        </h2>
      </div>

      <div className="p-8 grid grid-cols-1 md:grid-cols-2 gap-8">
        {/* Bakım Modu */}
        <div className={`p-6 rounded-[2rem] border transition-all ${settings.maintenance_mode ? 'bg-red-50 border-red-200' : 'bg-gray-50 border-gray-100'}`}>
          <div className="flex items-center justify-between mb-4">
            <div className={`p-3 rounded-2xl ${settings.maintenance_mode ? 'bg-red-500 text-white' : 'bg-gray-200 text-gray-500'}`}>
              <ShieldCheck size={24} />
            </div>
            <button
              onClick={() => handleToggle('maintenance_mode')}
              disabled={loading === 'maintenance_mode'}
              className={`relative inline-flex h-8 w-14 items-center rounded-full transition-colors focus:outline-none ${settings.maintenance_mode ? 'bg-red-500' : 'bg-gray-300'}`}
            >
              <span className={`inline-block h-6 w-6 transform rounded-full bg-white transition-transform ${settings.maintenance_mode ? 'translate-x-7' : 'translate-x-1'}`} />
            </button>
          </div>
          <h3 className="text-lg font-black text-gray-900 mb-1">Bakım Modu</h3>
          <p className="text-xs text-gray-500 font-medium leading-relaxed">
            Aktif edildiğinde, adminler hariç tüm kullanıcılar "Bakımdayız" sayfasına yönlendirilir.
          </p>
          {settings.maintenance_mode && (
            <div className="mt-4 flex items-center gap-2 text-red-600 font-black text-[10px] uppercase tracking-widest">
              <Activity size={12} className="animate-pulse" />
              Sistem Şu An Kilitli
            </div>
          )}
        </div>

        {/* Ses Klonlama */}
        <div className={`p-6 rounded-[2rem] border transition-all ${settings.voice_cloning_enabled ? 'bg-sky-50 border-sky-200' : 'bg-gray-50 border-gray-100'}`}>
          <div className="flex items-center justify-between mb-4">
            <div className={`p-3 rounded-2xl ${settings.voice_cloning_enabled ? 'bg-sky-500 text-white' : 'bg-gray-200 text-gray-500'}`}>
              <Volume2 size={24} />
            </div>
            <button
              onClick={() => handleToggle('voice_cloning_enabled')}
              disabled={loading === 'voice_cloning_enabled'}
              className={`relative inline-flex h-8 w-14 items-center rounded-full transition-colors focus:outline-none ${settings.voice_cloning_enabled ? 'bg-sky-500' : 'bg-gray-300'}`}
            >
              <span className={`inline-block h-6 w-6 transform rounded-full bg-white transition-transform ${settings.voice_cloning_enabled ? 'translate-x-7' : 'translate-x-1'}`} />
            </button>
          </div>
          <h3 className="text-lg font-black text-gray-900 mb-1">Ses Klonlama Özelliği</h3>
          <p className="text-xs text-gray-500 font-medium leading-relaxed">
            Kullanıcıların kendi seslerini yükleyip masal okutma özelliğini açar veya kapatır.
          </p>
          {!settings.voice_cloning_enabled && (
            <div className="mt-4 text-orange-600 font-black text-[10px] uppercase tracking-widest">
              Özellik Devre Dışı
            </div>
          )}
        </div>
      </div>
    </div>
  )
}
